-- ============================================================================
-- V60: Tabla de unidades policiales institucionales y precarga inicial.
-- Apply to: MASTER database (Secad)
--
-- Réplica exacta de la estructura de unidades institucionales con sus 74 campos,
-- utilizada para parametrizar departamentos, municipios, códigos DANE y siglas
-- de unidades en el registro de tenants/CADs y módulos de gestión territorial.
-- ============================================================================

CREATE TABLE IF NOT EXISTS secad_unidades (
    fuerza NUMERIC(3,0),
    consecutivo NUMERIC(12,2) PRIMARY KEY,
    descripcion_dependencia VARCHAR(250) NOT NULL,
    vigente VARCHAR(10) DEFAULT 'SI',
    nivel_jerarquico VARCHAR(10),
    nivel_organizacional NUMERIC(10,2),
    nivel_funcional VARCHAR(10),
    ordenamiento NUMERIC(10,2),
    nit NUMERIC(15,2),
    direccion VARCHAR(250),
    email VARCHAR(150),
    orden_publico VARCHAR(10),
    prima_clima VARCHAR(10),
    partida_de_alimentacion VARCHAR(10),
    nomina VARCHAR(10),
    indicativo_microondas NUMERIC(10,0),
    fecha_activacion TIMESTAMP WITH TIME ZONE,
    fecha_desactivacion TIMESTAMP WITH TIME ZONE,
    id_sigla NUMERIC(10,2),
    tiun_codigo NUMERIC(10,2),
    depe_codigo NUMERIC(10,2),
    depe_codigo_pertenece NUMERIC(10,2),
    depe_codigo_corresponder NUMERIC(10,2),
    empl_unde_consecutivo NUMERIC(12,2),
    empl_unde_fuerza NUMERIC(3,0),
    empl_consecutivo NUMERIC(12,2),
    regi_codigo NUMERIC(10,2),
    barri_codigo NUMERIC(12,2),
    barri_luge_codigo NUMERIC(10,0),
    luge_codigo NUMERIC(10,0),
    guco_fuerza NUMERIC(3,0),
    guco_codigo NUMERIC(10,2),
    unde_fuerza NUMERIC(3,0),
    unde_consecutivo NUMERIC(12,2),
    creado_por VARCHAR(50),
    fecha_creacion TIMESTAMP WITH TIME ZONE,
    maquina_creacion VARCHAR(100),
    actualizado_por VARCHAR(50),
    fecha_actualiza TIMESTAMP WITH TIME ZONE,
    maquina_actualiza VARCHAR(150),
    dificultad VARCHAR(50),
    tipo_pago VARCHAR(10),
    sigla_papa VARCHAR(50),
    codigo_delegacion NUMERIC(10,2),
    nivel_riesgo NUMERIC(10,2),
    condicion_partida_alimentacion VARCHAR(20),
    telefono VARCHAR(50),
    categoria_unidad VARCHAR(50),
    centro_de_costos VARCHAR(50),
    prima_carabinero VARCHAR(10),
    sigla_depende VARCHAR(50),
    sigla_fisica VARCHAR(50),
    submarinista VARCHAR(10),
    zona_critica VARCHAR(10),
    tipo_dotacion NUMERIC(10,2),
    sigla_sivicc VARCHAR(50),
    motivo_operacion VARCHAR(100),
    telefono_ip VARCHAR(50),
    disp_id_disposicion NUMERIC(10,2),
    numero_disposicion VARCHAR(50),
    fecha_disposicion TIMESTAMP WITH TIME ZONE,
    municipio VARCHAR(150),
    tipo_descripcion VARCHAR(20),
    codigo_padre NUMERIC(10,0),
    departamento_padre VARCHAR(150),
    tipo_padre VARCHAR(20),
    codigo_departamento NUMERIC(10,0),
    departamento VARCHAR(150),
    tipo VARCHAR(20),
    zona VARCHAR(20),
    codigo_dane VARCHAR(20),
    desc_regional VARCHAR(150),
    cod_regional NUMERIC(10,2),
    fecha_actualiza_vm TIMESTAMP WITH TIME ZONE
);

CREATE INDEX IF NOT EXISTS idx_secad_unidades_departamento ON secad_unidades(departamento);
CREATE INDEX IF NOT EXISTS idx_secad_unidades_municipio ON secad_unidades(municipio);
CREATE INDEX IF NOT EXISTS idx_secad_unidades_codigo_dane ON secad_unidades(codigo_dane);
CREATE INDEX IF NOT EXISTS idx_secad_unidades_sigla_fisica ON secad_unidades(sigla_fisica);
CREATE INDEX IF NOT EXISTS idx_secad_unidades_vigente ON secad_unidades(vigente);

-- Precarga de las 35 unidades/municipios institucionales del export
